SELECT id, project_name, city, region, address, avg_price, highlights, discount_info, handover_date, status FROM crm_project WHERE 1 = 1
AND (project_name LIKE CONCAT('%', #{query.keyword}, '%') OR address LIKE CONCAT('%', #{query.keyword}, '%'))
AND region = #{query.region}
AND status = #{query.status}
ORDER BY updated_at DESC, id DESC
